                        while not Path(step['release']).exists():
                            if time.monotonic()>deadline:raise TimeoutError('mock barrier timed out')
                            time.sleep(.01)
                        return step['reply']
                    actions.append(delayed)
            scripts[ident]=actions
    return MockProvider(directory,scripts)


def parser():
    root=argparse.ArgumentParser(description='Prepare access requests for human review. Security Review assesses risk and forwards its recommendation to the system owner for a human decision; a manager is a contact.')
    commands=root.add_subparsers(dest='command',required=True)
